import Board from "./components/Board";
import { useBoard } from "./hooks/useBoard";

function App() {
  const { board } = useBoard();

  return (
    <div style={{ padding: 20,backgroundColor:"rgb(16,22,62)"  }}>
      <Board board={board} />
    </div>
  );
}

export default App;
